---@class GachaponShared : Singleton
---@field GetInstance fun(self:GachaponShared):GachaponShared
local GachaponShared = Class('GachaponShared', Singleton)


function GachaponShared:__init()
    ---@type table<string, UnityEngine.Coroutine> @ 纯异步加载的协程map（key：路径，value：加载协程）
    self._loadCoAsync = nil
    
    ---@type table<string, UnityEngine.Coroutine> @ 加载并实例化资源的协程map（key：路径，value：加载协程）
    self._loadCo = nil
    
    ---@type table<string, Engine.Modules.AbstractResourceLoader> @ 加载完成的loader对象map（key：路径，value：加载协程）
    self._loadCoLoader = nil

    ---@type table<string, UnityEngine.GameObject> @ 加载完成的实例对象map（key：路径，value：对象）
    self._loadedRes = nil

    ---@type table<string, UnityEngine.GameObject> @ 加载完成的资源对象map（key：路径，value：对象）
    self._loadedAssets = nil

    self._prevScene = nil
end

function GachaponShared:__delete()
    self._loadedRes = nil
    self._loadCo = nil
    self._loadCoAsync = nil
    self._loadCoLoader = nil
    self._loadedAssets = nil
    self._prevScene = nil
    self:SetTempContent(nil)
end

function GachaponShared:DisposeAll()
    self:DisposeCo()             -- 先停掉所有协程
    self:DisposeAllModel()       -- 销毁全部加载对象
    self:DisposeLoader()         -- 销毁全部加载器
    self:DelLoadModelParentGo()  -- 销毁根级父级对象
    CS.Engine.Modules.AbstractResourceLoader.LastGcTime = 0 ---强制刷新一次释放
    printInfo("DisposeAll")
end


function GachaponShared:DisposeAllModel()
    if self._loadedRes ~= nil then
        for k, v in pairs(self._loadedRes) do
            if not isNull(v) and type(v) ~= 'boolean' then
                GameObject.Destroy(v)
            end
        end
        self._loadedRes = nil
    end
    self._loadedAssets = nil
end

function GachaponShared:DisposeEnterAnim(data)
    for k, v in pairs(data or {}) do
        self:DisposeSingle(v)
    end
end

---@param path string
function GachaponShared:DisposeSingle(path)
    -- 清实例对象
    if isSet(self._loadedRes, path) then
        if not isNull(self._loadedRes[path])  then
            GameObject.Destroy(self._loadedRes[path])
        end
        self._loadedRes[path] = nil
    end
end

---@param path string
function GachaponShared:DisposeLoaderSingle(path)
    --- 清loader
    if self._loadCoLoader then
        local loader = self._loadCoLoader[path]
        if isNotNull(loader) then
            loader:Release()
        end
        self._loadCoLoader[path] = nil
    end
    -- 清加载协程
    if self._loadCoAsync then
        local loadCo = self._loadCoAsync[path]
        if isNotNull(loadCo) then
            cs_coroutine.stop(loadCo)
        end
        self._loadCoAsync[path] = nil
    end
end

function GachaponShared:DisposeLoader()
    ---@param loader Engine.Modules.AbstractResourceLoader
    for k, loader in pairs(self._loadCoLoader or {}) do
        if not isNull(loader) then
            loader:Release()
        end
        self._loadCoLoader[k] = nil
    end
end

function GachaponShared:DisposeCo()
    if self._loadCo ~= nil then
        for k, v in pairs(self._loadCo) do
            --CS.CoroutineModule.Instance:StopCo(v)
            cs_coroutine.stop(v)
        end
        self._loadCo = nil
    end
    
    if self._loadCoAsync ~= nil then
        for k, v in pairs(self._loadCoAsync) do
            --CS.CoroutineModule.Instance:StopCo(v)
            cs_coroutine.stop(v)
        end
        self._loadCoAsync = nil
    end
end

---@return boolean
function GachaponShared:HasLoadModelParentGo()
    local sceneSettingId  = GachaponConstants.GachaponGuideAnimSceneDefine.SCENE_ID
    local sceneInstance   = self:GetAppendedScene(sceneSettingId)
    local gachaponCacheGo = nil
    if not isNull(sceneInstance) then
        gachaponCacheGo = sceneInstance:GetCacheObjectByName("GachaponCache")
        if not isNull(gachaponCacheGo) then
            return true
        end
    end
    return false
end

---@return UnityEngine.GameObject
function GachaponShared:GetLoadModelParentGo()
    local sceneSettingId  = GachaponConstants.GachaponGuideAnimSceneDefine.SCENE_ID
    local sceneInstance   = self:GetAppendedScene(sceneSettingId)
    local gachaponCacheGo = nil
    if not isNull(sceneInstance) then
        gachaponCacheGo = sceneInstance:GetCacheObjectByName("GachaponCache")
        if isNull(gachaponCacheGo) then
            gachaponCacheGo = GameObject("GachaponCache")
            sceneInstance:AddCacheObject(gachaponCacheGo)
            SceneManager.MoveGameObjectToScene(gachaponCacheGo, sceneInstance:GetScene())
        end
    end
    return gachaponCacheGo
end

function GachaponShared:DelLoadModelParentGo()
    local sceneSettingId  = GachaponConstants.GachaponGuideAnimSceneDefine.SCENE_ID
    local sceneInstance   = self:GetAppendedScene(sceneSettingId)
    if not isNull(sceneInstance) then
        local gachaponCacheGo = sceneInstance:GetCacheObjectByName("GachaponCache")
        sceneInstance:RemoveCacheObjectByName("GachaponCache")
        if not isNull(gachaponCacheGo) then
            KTool.SafeDelete(gachaponCacheGo)
        end
    end
end

function GachaponShared:LoadModelAsync(path)
    if self._loadCoLoader == nil then
        self._loadCoLoader = {}
    end

    if isSet(self._loadCoLoader, path) then
        return false
    end

    if self._loadCoAsync == nil then
        self._loadCoAsync = {}
    end

    if isSet(self._loadCoAsync, path) then
        return true
    end

    local yieldFunc = cs_coroutine.start(function()
        --printInfo("LoadModel")
        coroutine.yield(Yielders.EndOfFrame)
        ---@param loader Engine.Modules.AbstractResourceLoader
        ---@param ok boolean
        ---@param resultObject UnityEngine.GameObject
        ResourceModule.LoadBundleAsync(path, function(loader, ok, resultObject)
            if ok then
                if self._loadCoAsync[path] then
                    if not isNull(resultObject) then
                        self._loadCoLoader[path] = loader
                    end
                else
                    loader:Release()
                end
        
                printInfo("pre-loader finish " .. path)
                --printInfo("LoadModel end")
        
                printInfo("pre-loader refcount " .. tostring(loader.RefCount))
                self._loadCoAsync[path] = nil
            end
            -- loader:Release()
        end)
    end)

    if self._loadCoAsync == nil then
        self._loadCoAsync = {}
    end
    
    if self._loadCoLoader == nil then
        self._loadCoLoader = {}
    end

    self._loadCoAsync[path] = yieldFunc

    return true
end

function GachaponShared:LoadModel(path, callback, parent)
    if self._loadedRes == nil then
        self._loadedRes = {}
    end

    if self._loadedAssets == nil then
        self._loadedAssets = {}
    end

    if isSet(self._loadedRes, path) then
        if callback ~= nil then
            callback(self._loadedRes[path])
        end
        return false
    end

    if isSet(self._loadedAssets, path) then
        if callback ~= nil then
            callback(self._loadedAssets[path])
        end
        return false
    end

    if isSet(self._loadCo, path) then
        return true
    end


    local yieldFunc = cs_coroutine.start(function()
        --printInfo("LoadModel")
        -- coroutine.yield(Yielders.EndOfFrame)

        local isAssets = false
        local asyncLoader = self._loadCoLoader and self._loadCoLoader[path] or nil
        if not isNull(asyncLoader) then
            local modelIns = asyncLoader:Instantiate(false, parent, false)
            if modelIns then
                self._loadedRes[path] = modelIns
            else
                -- 资源类型，直接使用 result 源
                isAssets = true
                modelIns = asyncLoader.ResultObject
                asyncLoader:Retain(parent)
                self._loadedAssets[path] = modelIns
            end
            printInfo("asyncLoader instantiate " .. path)
        else
            local modelLoader = ResourceModule.LoadBundleAsync(path, nil, false)
            while not modelLoader.IsCompleted do
                coroutine.yield(Yielders.EndOfFrame)
            end
            if not isNull(modelLoader.ResultObject) then
                if not self._loadedRes[path] then
                    local modelIns = modelLoader:Instantiate(false, parent, false)
                    if modelIns then
                        self._loadedRes[path] = modelIns
                    else
                        -- 资源类型，直接使用 result 源
                        isAssets = true
                        modelIns = modelLoader.ResultObject
                        modelLoader:Retain(parent)
                        self._loadedAssets[path] = modelIns
                    end
                end
            else
                self._loadedRes[path] = false
            end
    
            printInfo("load finish " .. path)
            --printInfo("LoadModel end")
            modelLoader:Release()
    
            printInfo("loader refcount " .. tostring(modelLoader.RefCount))
        end
        if self._loadCo == nil then
            self._loadCo = {}
        end
        self._loadCo[path] = nil

        if callback ~= nil then
            callback(self._loadedRes[path] or self._loadedAssets[path])
        end

        --printInfo("_loadedRes")
        --print(table.dump(self._loadedRes))
    end)

    --local co = CoWait.Start():Coroutine(yieldFunc)
    if self._loadCo == nil then
        self._loadCo = {}
    end

    self._loadCo[path] = yieldFunc

    return true
end

---@param path string
---@param gameObject UnityEngine.GameObject
---@deprecated 将节点转移到  gachaponCach 中保存起来
function GachaponShared:SetParentToGo(gameObject)
     if not isNull(gameObject) then
        gameObject.transform:SetParent(self:GetLoadModelParentGo().transform , false)
        KTool.SetActive(gameObject, false)
    end
end


---@param path string
---@return UnityEngine.GameObject | nil
function GachaponShared:GetModel(path)
    local modelObj = nil
    if isSet(self._loadedRes, path) then
        if type(self._loadedRes[path]) ~= 'boolean' then
            modelObj = self._loadedRes[path]
        end
    end
    if modelObj == nil then
        if isSet(self._loadedAssets, path) then
            if type(self._loadedAssets[path]) ~= 'boolean' then
                modelObj = self._loadedAssets[path]
            end
        end
    end
    return modelObj
end

---@param path string
---@return UnityEngine.GameObject | nil
function GachaponShared:CloneModle(path)
    local modle = self:GetModel(path)
    if not isNull(modle) then
        local duplicate = GameObject.Instantiate(modle)
        KTool.SetActive(duplicate, false)
    end
    return nil
end

function GachaponShared:LoadSpriteAsync(imageComp, path, nativeSize)
    if isNull(imageComp) then
        return
    end

    KTool.SetActive(imageComp.gameObject, false)

    --local _loader =
    CSGameUtils.GetSpriteByStringUrlByOwner(path, imageComp, function(sprite)
        --printInfo("GameUtils.LoadSprite")
        if KTool.IsNull(imageComp) then
            return
        end
        if not KTool.IsNull(sprite) then
            if imageComp:GetType() == typeof(CS.UnityEngine.UI.Image) then
                imageComp.sprite = sprite
            else
                imageComp.texture = sprite.texture
            end
            
            if nativeSize then
                imageComp:SetNativeSize()
            end

            KTool.SetActive(imageComp.gameObject, true)
        end
    end)
end

function GachaponShared:WaitForSceneLoad(id)
    return cs_coroutine.start(function()
        coroutine.yield(SceneManagement:AppendScene(id, true))
        local sceneData = SceneManagement:GetScenePathInfo(id)
        SceneManagement:Transition({ identifier = sceneData.id, isCache = true })
        while SceneManagement:IsTransition() do
            coroutine.yield()
        end
        --SceneManagement:SetActive(id, true)
    end)
end

---@return SceneInstance
function GachaponShared:GetAppendedScene(id)
    return SceneManagement:GetSceneInstance(id)
end

---@param sceneIns SceneInstance
function GachaponShared:SetSceneActive(sceneIns)
    self._prevScene = SceneManager:GetActiveScene()
    SceneManagement:SetSceneActive(sceneIns:GetScene())
end

function GachaponShared:UnloadScene(id)
    cs_coroutine.yield_return(SceneManagement:UnloadAppendedSceneById(id))
    SceneManagement:SetSceneActive(self._prevScene)
    self._prevScene = nil
end

function GachaponShared:SetTempContent(contentBgGo)
    if not isNull(self.tempContentBgGo_) then
        CfUtils.SafeDelete(self.tempContentBgGo_)
    end
    self.tempContentBgGo_ = contentBgGo
end

return GachaponShared